const existing = $('Airtable \u2014 Cours existants').all().map(i => i.json.Titre || '').filter(Boolean);

const allSources = [];

const rssNodes = [
  { name: 'Formation Afrique', node: 'Alerte \u2014 Formation marketing Afrique' },
  { name: 'Courses trends', node: 'Alerte \u2014 Online courses trends' },
  { name: 'Udemy', node: 'Alerte \u2014 Udemy marketing digital' },
  { name: 'Coursera', node: 'Alerte \u2014 Coursera marketing francophone' },
  { name: 'OpenClassrooms', node: 'RSS \u2014 OpenClassrooms' },
  { name: 'Comp\u00e9tences emploi', node: 'Alerte \u2014 Comp\u00e9tences num\u00e9riques emploi Afrique' },
  { name: 'Startups Afrique', node: 'Alerte \u2014 Startups & incubateurs Afrique Ouest' },
  { name: 'EdTech Afrique', node: 'GNews \u2014 EdTech Afrique formation' },
  { name: 'Certifications', node: 'GNews \u2014 Certification professionnelle Afrique' },
  { name: 'Emploi digital', node: 'GNews \u2014 Emploi digital Afrique Ouest' },
  { name: 'YT Marketing FR', node: 'YouTube XML \u2014 Cours marketing FR' },
  { name: 'YT Max-Morrys', node: 'YouTube XML \u2014 Max-Morrys' }
];

for (const src of rssNodes) {
  try {
    const items = $(src.node).all();
    for (const item of items.slice(0, 5)) {
      const j = item.json;
      allSources.push({ title: j.title || '', snippet: (j.contentSnippet || j.content || '').substring(0, 300), url: j.link || '', source: src.name });
    }
  } catch (e) {}
}

let formationRequests = [];
try {
  const msgs = $('Firestore \u2014 Demandes de formation').first().json;
  formationRequests = (msgs?.documents || []).filter(doc => {
    const s = (doc.fields?.subject?.stringValue || '').toLowerCase();
    return s.includes('formation') || s.includes('cours') || s.includes('apprendre');
  }).map(doc => ({
    title: doc.fields?.subject?.stringValue || '',
    snippet: (doc.fields?.message?.stringValue || '').substring(0, 200),
    url: '', source: 'Demandes visiteurs'
  }));
} catch(e) {}

return [{ json: {
  existing_courses: existing,
  rss_results: allSources,
  formation_requests: formationRequests,
  total_sources: allSources.length + formationRequests.length
} }];

const input = $input.first().json;
const today = new Date().toISOString().split('T')[0];

// Robust extraction: handle markdown code fences, truncation, nested .content.parts
function extractText(inp) {
  if (inp.content?.parts) return inp.content.parts.map(p => p.text || '').join('');
  if (inp.candidates?.[0]?.content?.parts) return inp.candidates[0].content.parts.map(p => p.text || '').join('');
  if (typeof inp === 'string') return inp;
  if (inp.text) return inp.text;
  return '';
}
function cleanupJson(txt) {
  // strip markdown fences ```json ... ```
  let s = String(txt || '').trim();
  s = s.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();
  // best-effort: cut at last closing brace if unterminated
  const last = s.lastIndexOf('}');
  if (last !== -1 && last < s.length - 1) s = s.slice(0, last + 1);
  return s;
}

let parsed;
try {
  if (input.course_proposals) { parsed = input; }
  else {
    const txt = extractText(input);
    if (!txt) { parsed = input; }
    else parsed = JSON.parse(cleanupJson(txt));
  }
} catch (e) {
  // Last resort: return empty list rather than crashing workflow
  return [];
}

const courses = (parsed.course_proposals || []).map(c => ({
  Date: today, Titre: c.title, Niveau: c.level,
  Audience: c.target_audience, Besoin_Local: c.why_needed_locally,
  Duree: `${c.estimated_duration_hours}h (${c.estimated_modules} modules, ${c.estimated_lessons} leçons)`,
  Score: c.priority_score, Status: 'nouveau',
  slug: c.slug_suggested, category: c.category,
  objectives: JSON.stringify(c.learning_objectives),
  prerequisites: JSON.stringify(c.prerequisites),
  outline: JSON.stringify(c.outline_preview),
  price_range: c.suggested_price_range,
  monetization: c.monetization_potential,
  sources: (c.inspiration_sources || []).join(', ')
}));

return courses.map(c => ({ json: c }));

